<script lang="ts">
 import {noteDiagramSpecs,type NoteDiagram} from '$lib/note-diagrams';
 let {diagram}:{diagram:NoteDiagram}=$props();
 const layout=$derived(noteDiagramSpecs[diagram.name].layout);
 const lanes=[[1,2],[2,1],[0,1],[1,2],[2,1]];
</script>
{#snippet card(index:number)}<div class="card"><strong>{diagram.items[index].title}</strong>{#each diagram.items[index].body.split('\n') as line}<p>{line}</p>{/each}</div>{/snippet}
{#snippet down()}<svg class="down" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v17m-6-6 6 6 6-6"/></svg>{/snippet}
{#if layout==='csrf-v2-architecture'}
 <section class="computer"><h4>{diagram.items[0].title}</h4><p>{diagram.items[0].body}</p><div class="parallel">{@render card(1)}{@render card(2)}</div><div class="storage">{@render card(3)}</div></section>
 <div class="parallel server-lanes">{#each [4,5] as i}<div><svg class="roundtrip" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3v18m-5-5 5 5 5-5M16 21V3m-5 5 5-5 5 5"/></svg><p class="boundary">Browser ↔ {diagram.items[i].title}</p><p class="boundary">HTTPS Request / Response</p>{@render card(i)}</div>{/each}</div>
{:else if layout==='csrf-v2-scenarios'}
 <ul class="scenarios">{#each diagram.items as item,i}<li><svg viewBox="0 0 24 24" aria-hidden="true"><path d={['M8 15l7-7M7 12l-2 2a4 4 0 0 0 6 6l2-2M12 7l2-2a4 4 0 1 1 6 6l-2 2','M3 4h18v16H3V4Zm0 13 6-6 4 4 3-3 5 5M14 8h1','M3 5h18v14H3V5Zm0 5h18','M3 7h14m-5-5 5 5-5 5M21 17H7m5-5-5 5 5 5','M3 5h12v14H3V5Zm12 5 6-4v12l-6-4'][i]}/></svg><div><strong>{item.title}</strong>{#each item.body.split('\n') as line}{#if line.startsWith('<img')}<pre><code>{line}</code></pre>{:else}<p>{line}</p>{/if}{/each}</div></li>{/each}</ul>
{:else if layout==='csrf-v2-request'}
 <ol class="request-flow">{#each diagram.items as item,i}<li><div><strong>{item.title}</strong><p>{item.body}</p></div>{#if i<2}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12h17m-6-6 6 6-6 6"/></svg>{/if}</li>{/each}</ol>
{:else if layout==='csrf-v2-outcomes'}
 <ul class="outcomes">{#each diagram.items as item,i}<li class:warning={i===3}><svg viewBox="0 0 24 24" aria-hidden="true"><path d={i<2?'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm-3 6 6 6m0-6-6 6':i===2?'M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7l8-4Zm-4 9 3 3 5-6':'M12 3 2 21h20L12 3Zm0 6v6m0 2v1'}/></svg><div><strong>{item.title}</strong><p>{item.body}</p></div></li>{/each}</ul>
{:else if layout==='csrf-v2-conditions'}
 <div class="conditions"><div class="condition-root">{@render card(0)}</div><p class="boundary">四類並列條件，需共同成立</p>{@render down()}<div class="condition-groups">{#each noteDiagramSpecs.m20d2rconditions.groups as children,i}<section><div class="condition-parent">{@render card(i+1)}</div><ul aria-label={diagram.items[i+1].title+'的條件'}>{#each children as child}<li>{@render card(child)}</li>{/each}</ul></section>{/each}</div></div>
{:else if layout==='csrf-v2-decisions'}
 <ol class="decisions">{#each diagram.items as item,i}<li><strong>{item.title}</strong><p>{item.body}</p>{#if i<2}{@render down()}{/if}</li>{/each}</ol>
{:else if layout==='csrf-browser'}
 <div class="architecture"><div class="parallel">{@render card(0)}{@render card(1)}</div><p class="boundary">不同的網頁執行安全環境；無法任意互讀資料</p>{@render down()}<section class="browser-group"><h4>{diagram.items[2].title}</h4><p>{diagram.items[2].body}</p><div class="parallel">{@render card(3)}{@render card(4)}</div></section>{@render down()}{@render card(5)}</div>
{:else if layout==='csrf-session'}
 <div class="parallel session">{@render card(0)}{@render card(1)}</div>
{:else if layout==='csrf-exchange'}
 <div class="exchange">{#each diagram.items as item}<section><h4>{item.title}</h4><!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to local code scrolling.) --><pre role="region" aria-label={item.title} tabindex="0"><code>{item.body}</code></pre></section>{/each}</div>
{:else if layout==='csrf-headers'}
 <dl class="headers">{#each diagram.items as item,i}<div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><path d={i===0?'M3 12h17m-6-6 6 6-6 6':'M21 12H4m6-6-6 6 6 6'}/></svg>{item.title}</dt><dd>{item.body}</dd></div>{/each}</dl>
{:else if layout==='csrf-sequence'}
 <div class="actors" aria-hidden="true"><strong>惡意網頁</strong><strong>Alice Browser</strong><strong>銀行 Server</strong></div>
 <ol class="sequence">{#each diagram.items as item,i}<li style:--from={Math.min(...lanes[i])} style:--to={Math.max(...lanes[i])} class:reply={lanes[i][0]>lanes[i][1]} class={'step step-'+i}><div class="message"><strong>{item.title}</strong><p class="direction">{item.body}</p><svg class="arrow" viewBox="0 0 400 24" preserveAspectRatio="none" aria-hidden="true"><path d={lanes[i][0]<lanes[i][1]?'M2 12H395m-8-7 8 7-8 7':'M398 12H5m8-7-8 7 8 7'}/></svg></div></li>{/each}</ol>
 <p class="boundary">Cookie 未直接交給惡意網頁</p>
{:else if layout==='csrf-origins'||layout==='csrf-samesite'}
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to local table scrolling.) -->
 <div class="comparison" role="region" aria-label={diagram.caption} tabindex="0"><table><thead><tr><th scope="col">{layout==='csrf-origins'?'其他網址':'請求情境'}</th>{#each (layout==='csrf-origins'?['Origin','Site']:['Strict','Lax','None']) as label}<th scope="col">{label}</th>{/each}</tr></thead><tbody>{#each diagram.items as item}<tr><th scope="row">{item.title}</th>{#each item.body.split('｜') as cell}{@const value=cell.split('：')[1]}<td class:yes={value==='相同'||value==='允許'} class:no={value==='不同'||value==='不允許'}><span aria-hidden="true">{value==='相同'||value==='允許'?'✓':'×'}</span><span>{value}</span></td>{/each}</tr>{/each}</tbody></table></div>
{:else}
 <ol class="token">{#each diagram.items as item,i}<li><span class="number" aria-hidden="true">{i+1}</span><div><strong>{item.title}</strong><p>{item.body}</p></div></li>{/each}</ol>
{/if}
