 .computer{padding:1rem;border:1px solid #d8dce0;border-radius:12px;margin-top:1rem}.storage{background:#edf4fa;border:1px solid #d8dce0;border-radius:12px}.storage .card{background:transparent}.roundtrip{display:block;margin:1rem auto .5rem}.server-lanes .card{background:transparent;border:1px solid #d8dce0}.scenarios,.outcomes{list-style:none;padding:0;margin:1rem 0}.scenarios li,.outcomes li{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.75rem;padding:1.25rem 0;border-bottom:1px solid #d8dce0}.scenarios svg,.outcomes svg{margin-top:.4rem;color:#657079}.outcomes .warning svg{color:#b52323}.request-flow{list-style:none;padding:1rem 0;margin:1rem 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.request-flow li{display:grid;grid-template-columns:minmax(0,1fr) 24px;gap:.5rem;align-items:center;text-align:center}.request-flow li:last-child{grid-template-columns:minmax(0,1fr)}.decisions{list-style:none;padding:0;margin:1rem 0}.decisions li{padding:1rem 0;min-width:0}
